#!/usr/bin/env bash
# Office Simulator 3.0.0 · Установщик для macOS и Linux
# Запуск мастера: bash install.sh     Справка: bash install.sh --help
office_install() (
    set -eu
    umask 077
    python_bin=
    for candidate in python3 python3.15 python3.14 python3.13 python3.12 python3.11; do
        if command -v "$candidate" >/dev/null 2>&1 &&
           "$candidate" -I -c 'import sys; sys.exit(sys.version_info < (3, 11))' 2>/dev/null; then
            python_bin=$candidate
            break
        fi
    done
    if [ -z "$python_bin" ]; then
        echo "На компьютере администратора требуется Python 3.11 или новее. Установите его и повторите команду." >&2
        exit 1
    fi
    office_tmp=$(mktemp -d "${TMPDIR:-/tmp}/office-installer.XXXXXXXX")
    trap 'rm -rf -- "$office_tmp"' EXIT
    trap 'exit 130' INT
    trap 'exit 143' TERM HUP
    "$python_bin" -I -B -c '
import base64, hashlib, io, os, sys, zipfile
from pathlib import Path, PurePosixPath
try:
    payload = base64.b64decode(b"".join(sys.stdin.buffer.read().split()), validate=True)
    if len(payload) != 2051343 or hashlib.sha256(payload).hexdigest() != "395dda19ca8d344eeed196f52eb04c03c4ae55cf6575cd0f1ec14626fc674db8":
        raise ValueError
    with zipfile.ZipFile(io.BytesIO(payload)) as archive:
        for item in archive.infolist():
            name = PurePosixPath(item.filename)
            if name.is_absolute() or ".." in name.parts or (item.external_attr >> 16) != 0o100600:
                raise ValueError
            target = Path(sys.argv[1]) / name
            target.parent.mkdir(parents=True, exist_ok=True)
            with target.open("xb") as file:
                file.write(archive.read(item))
except (ValueError, OSError, zipfile.BadZipFile):
    sys.exit("Не удалось проверить и распаковать комплект Office Simulator.")
' "$office_tmp" <<'OFFICE_SIMULATOR_PAYLOAD'
